interface.signature:
GET /api/conversations -> { conversations: Conversation[], total: number }
POST /api/conversations -> { id, title, created_at }
GET /api/conversations/{id} -> { id, title, messages: Message[], created_at, updated_at, pagination }
DELETE /api/conversations/{id} -> { status: "deleted" }
PATCH /api/conversations/{id} { title } -> { id, title, updated_at }

interface Conversation {
  id: string;
  title: string;
  created_at: string;
  updated_at: string;
  message_count: number;
  last_message_preview: string | null;
}

interface AppState {
  // Conversations
  conversations: Conversation[];
  activeConversationId: string | null;

  // Actions
  setActiveConversation: (id: string | null) => void;
  addConversation: (conversation: Conversation) => void;
  removeConversation: (id: string) => void;
  updateConversation: (id: string, updates: Partial<Conversation>) => void;
  setConversations: (conversations: Conversation[]) => void;
}

function useConversations(): {
  conversations: Conversation[];
  isLoading: boolean;
  error: string | null;
  fetchConversations: () => Promise<void>;
  createConversation: () => Promise<Conversation>;
  deleteConversation: (id: string) => Promise<void>;
  renameConversation: (id: string, title: string) => Promise<void>;
}
